package com.greenocean.backend;

import com.greenocean.backend.moderation.service.SocialAttribution;
import com.greenocean.backend.auth.repository.UserRepository;
import com.greenocean.backend.auth.service.TokenService;
import com.greenocean.backend.common.exception.*;
import com.greenocean.backend.professional.service.PrivateDocumentCipher;
import com.greenocean.backend.trust.SafeTelemetry;
import com.greenocean.backend.wellbeing.service.PrivateWellbeing;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.MediaType;
import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"greenocean.trust.enabled=true","greenocean.telemetry.enabled=true","greenocean.security.admin-enabled=true"}) @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseQ2SecurityTest extends PhaseLFixtures {
 @Autowired SocialAttribution evidence;@Autowired UserRepository users;@Autowired TokenService tokens;@Autowired PrivateWellbeing privateData;@Autowired SafeTelemetry telemetry;
 @Autowired com.greenocean.backend.account.repository.AccountRepository accountRepository;
 @Autowired com.greenocean.backend.account.service.AccountService accounts;
 @Autowired com.greenocean.backend.trust.TrustCoverage coverage;
 Member author;
 @BeforeEach void eligibleSource()throws Exception{author=member();}
 PhaseIFixtures.Actor actor(String... roles){var a=PhaseIFixtures.member(db,users,tokens);for(String r:roles)db.update("INSERT INTO user_roles(user_id,role_id) SELECT ?,id FROM roles WHERE name=? ON CONFLICT DO NOTHING",a.id(),r);entities.clear();String token=tokens.createAccessToken(users.findById(a.id()).orElseThrow(),a.session());db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP WHERE id=?",a.session());return new PhaseIFixtures.Actor(a.id(),a.session(),token);}
 UUID held()throws Exception{String p=publish(author,"A synthetic quoted privacy link https://example.test/context",true).path("id").asText();return db.queryForObject("SELECT id FROM social_assessments WHERE post_id=?",UUID.class,UUID.fromString(p));}
 UUID request(PhaseIFixtures.Actor a,UUID id){return evidence.request(a.id(),a.session(),id,1,"PRIVACY_COMPLAINT");}
 @Test @Tag("happy") void erasingAcknowledgedTrustOperatorReleasesSessionReferencesAndCapacity(){var a=actor("TRUST_SOCIAL");var b=actor("TRUST_SOCIAL","TRUST_PLATFORM");UUID shift=coverage.schedule(b.id(),b.session(),"SOCIAL",a.id(),java.time.Instant.now().minusSeconds(30),java.time.Instant.now().plusSeconds(3600),1);coverage.acknowledge(a.id(),a.session(),shift);assertThat(coverage.live("SOCIAL",a.id())).isTrue();accountRepository.erase(a.id());assertThat(db.queryForObject("SELECT session_id IS NULL AND token_version IS NULL AND revoked_at IS NOT NULL FROM trust_coverage WHERE id=?",Boolean.class,shift)).isTrue();assertThat(db.queryForObject("SELECT count(*) FROM user_sessions WHERE user_id=?",Integer.class,a.id())).isZero();assertThat(coverage.live("SOCIAL",a.id())).isFalse();}
 @Test @Tag("happy") void archiveMinimizesExceptionalEvidenceAndErasureRevokesStaffWithoutSessionForeignKeyBlock()throws Exception{var a=actor("ADMIN");var b=actor("ADMIN");UUID id=held(),r=request(a,id);evidence.approve(b.id(),b.session(),r,1);String archive=json.writeValueAsString(accounts.archive(a.id()).trustAndSecurity());assertThat(archive).contains(r.toString(),"PRIVACY_COMPLAINT").doesNotContain(b.id().toString(),a.session().toString(),b.session().toString(),author.id().toString(),"quoted privacy link");accountRepository.erase(b.id());assertThat(db.queryForObject("SELECT count(*) FROM user_sessions WHERE user_id=?",Integer.class,b.id())).isZero();assertThat(db.queryForObject("SELECT revoked_at IS NOT NULL FROM social_attribution_requests WHERE id=?",Boolean.class,r)).isTrue();assertThatThrownBy(()->evidence.reveal(a.id(),a.session(),id,r)).isInstanceOf(ConflictException.class);}
 @Test @Tag("happy") void erasingAnonymousSourceCascadesAttributionRequestsWithoutLeakingOrBlocking()throws Exception{var a=actor("ADMIN");var b=actor("ADMIN");UUID id=held(),r=request(a,id);evidence.approve(b.id(),b.session(),r,1);accountRepository.erase(author.id());assertThat(db.queryForObject("SELECT count(*) FROM social_attribution_requests WHERE id=?",Integer.class,r)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM user_sessions WHERE user_id=?",Integer.class,author.id())).isZero();assertThatThrownBy(()->evidence.reveal(a.id(),a.session(),id,r)).isInstanceOf(NotFoundException.class);}
 @Test @Tag("happy") void independentAttributionIsOneUseAndNeverEntersOrdinaryProjection()throws Exception{var a=actor("ADMIN");var b=actor("ADMIN");UUID id=held(),r=request(a,id);assertThatThrownBy(()->evidence.reveal(a.id(),a.session(),id,r)).isInstanceOf(ForbiddenException.class);assertThatThrownBy(()->evidence.approve(a.id(),a.session(),r,1)).isInstanceOf(ForbiddenException.class);evidence.approve(b.id(),b.session(),r,1);assertThat(evidence.reveal(a.id(),a.session(),id,r)).containsEntry("authorId",author.id());assertThatThrownBy(()->evidence.reveal(a.id(),a.session(),id,r)).isInstanceOf(ConflictException.class);assertThat(read("/api/v1/social-moderation/me",author).toString()).doesNotContain(a.id().toString(),b.id().toString());}
 @Test @Tag("malicious") void unreportedAllowedContentCannotBeDeAnonymized()throws Exception{var a=actor("ADMIN");String post=publish(author,"A legitimate anonymous story with no safety concern",true).path("id").asText();UUID id=db.queryForObject("SELECT id FROM social_assessments WHERE post_id=?",UUID.class,UUID.fromString(post));assertThatThrownBy(()->request(a,id)).isInstanceOf(ForbiddenException.class);}
 @Test @Tag("malicious") void revokedReviewerSessionAndChangedTokenVersionInvalidateApproval()throws Exception{var a=actor("ADMIN");var b=actor("ADMIN");UUID id=held(),r=request(a,id);evidence.approve(b.id(),b.session(),r,1);db.update("UPDATE user_sessions SET token_version=token_version+1 WHERE id=?",b.session());assertThatThrownBy(()->evidence.reveal(a.id(),a.session(),id,r)).isInstanceOf(ConflictException.class);db.update("UPDATE user_sessions SET revoked_at=CURRENT_TIMESTAMP WHERE id=?",b.session());assertThatThrownBy(()->evidence.reveal(a.id(),a.session(),id,r)).isInstanceOf(UnauthorizedException.class);}
 @Test @Tag("creative") void anotherDeviceCannotBorrowAnEvidenceGrant()throws Exception{var a=actor("ADMIN");var b=actor("ADMIN");UUID id=held(),r=request(a,id);evidence.approve(b.id(),b.session(),r,1);var other=PhaseIFixtures.session(db,users,tokens,a.id());db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP WHERE id=?",other.session());assertThatThrownBy(()->evidence.reveal(a.id(),other.session(),id,r)).isInstanceOf(NotFoundException.class);}
 @Test @Tag("malicious") void evidencePurposeIsFixedAndNarrativesAreNotAccepted()throws Exception{var a=actor("ADMIN");UUID id=held();assertThatThrownBy(()->evidence.request(a.id(),a.session(),id,1,"Private clinical narrative or arbitrary reason")).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->evidence.request(a.id(),a.session(),id,2,"PRIVACY_COMPLAINT")).isInstanceOf(ConflictException.class);}
 @Test @Tag("malicious") void revokedGrantCannotBeReapprovedOrUnrevoked()throws Exception{var a=actor("ADMIN");var b=actor("ADMIN");UUID id=held(),r=request(a,id);evidence.revoke(a.id(),a.session(),r);assertThatThrownBy(()->evidence.approve(b.id(),b.session(),r,1)).isInstanceOf(ConflictException.class);assertThatThrownBy(()->db.update("UPDATE social_attribution_requests SET revoked_at=NULL WHERE id=?",r)).isInstanceOf(org.springframework.dao.DataAccessException.class);}
 @Test @Tag("malicious") void staleEvidenceDoesNotRevealEditedRevision()throws Exception{var a=actor("ADMIN");var b=actor("ADMIN");UUID id=held(),r=request(a,id);evidence.approve(b.id(),b.session(),r,1);db.update("UPDATE posts SET revision=revision+1 WHERE id=(SELECT post_id FROM social_assessments WHERE id=?)",id);assertThatThrownBy(()->evidence.reveal(a.id(),a.session(),id,r)).isInstanceOf(ConflictException.class);}
 @Test @Tag("malicious") void currentRolesAndMfaAreRequiredForEvidence()throws Exception{var a=actor("ADMIN");UUID id=held();db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP-INTERVAL '1 hour' WHERE id=?",a.session());assertThatThrownBy(()->request(a,id)).isInstanceOf(ForbiddenException.class);db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP WHERE id=?",a.session());db.update("DELETE FROM user_roles WHERE user_id=? AND role_id=(SELECT id FROM roles WHERE name='ADMIN')",a.id());assertThatThrownBy(()->request(a,id)).isInstanceOf(UnauthorizedException.class);}
 @Test @Tag("malicious") void executableRoleMatrixDoesNotGrantJournalBrowsing()throws Exception{UUID id=(UUID)privateData.write(author.id(),null,new PrivateWellbeing.Writing("Private Q2 journal","PRIVATE_Q2_OWNER_ONLY",null,List.of(),0,UUID.randomUUID())).get("id");read("/api/v1/wellbeing/journal/"+id,author);for(String role:List.of("USER","ADMIN","MODERATOR","CLINIC_FINANCE","CLINICAL_RECORDS_OPERATOR","CLINIC_OPERATIONS","CLINIC_PRIVACY_OPERATOR","TRUST_SOCIAL","TRUST_EDUCATION","TRUST_PLATFORM")){var a=actor(role);mvc.perform(get("/api/v1/wellbeing/journal/"+id).header("Authorization","Bearer "+a.token())).andExpect(status().isNotFound());mvc.perform(delete("/api/v1/wellbeing/journal/"+id).header("Authorization","Bearer "+a.token())).andExpect(status().isNotFound());}assertThat(privateData.one(author.id(),"journal",id)).containsEntry("body","PRIVATE_Q2_OWNER_ONLY");}
 @Test @Tag("malicious") void revokedAndSuspendedActorsCannotReadEvenOwnPrivateData()throws Exception{var a=actor();db.update("UPDATE user_sessions SET revoked_at=CURRENT_TIMESTAMP WHERE id=?",a.session());mvc.perform(get("/api/v1/account/archive").header("Authorization","Bearer "+a.token())).andExpect(status().isUnauthorized());var b=actor();db.update("UPDATE users SET status='SUSPENDED' WHERE id=?",b.id());mvc.perform(get("/api/v1/wellbeing/journal").header("Authorization","Bearer "+b.token())).andExpect(status().isUnauthorized());}
 @Test @Tag("malicious") void largeJsonIsBoundedBeforeParsingAndNeverEchoed()throws Exception{String body="{\"body\":\"PRIVATE_MARKER_"+"x".repeat(1100000)+"\"}";for(String type:List.of("application/json","application/problem+json"))mvc.perform(post("/api/v1/auth/login").contentType(type).content(body)).andExpect(status().is(413)).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("PRIVATE_MARKER_"))));}
 @Test @Tag("confused") void telemetryContainsOnlyFixedAggregatesNotRequestIdentity()throws Exception{String unique=UUID.randomUUID().toString(),sentinel="PRIVATE_JOURNAL_SECRET";mvc.perform(get("/api/v1/posts/"+unique+"?q="+sentinel).header("Authorization","Bearer "+author.token())).andExpect(status().isNotFound());String result=json.writeValueAsString(telemetry.snapshot());assertThat(result).doesNotContain(unique,sentinel,author.email(),author.id().toString(),"Authorization","body");assertThat(result).contains("fixedService","statusFamily");}
 @Test @Tag("malicious") void ordinaryUserCannotReadOperationalMetrics()throws Exception{mvc.perform(get("/api/v1/trust/metrics").header("Authorization","Bearer "+author.token())).andExpect(status().isForbidden());var operator=actor("TRUST_PLATFORM");mvc.perform(get("/api/v1/trust/metrics").header("Authorization","Bearer "+operator.token())).andExpect(status().isOk());}
 @Test @Tag("creative") void authenticatedEncryptionSupportsRotationAndRejectsWrongOwnerKeyOrTampering(){String oldKey="AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=",newKey="AQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQEBAQE=";var original=new PrivateDocumentCipher("old:"+oldKey,"old");byte[] cipher=original.seal("PRIVATE_Q2_ROTATION".getBytes(java.nio.charset.StandardCharsets.UTF_8),"owner-a");var rotated=new PrivateDocumentCipher("old:"+oldKey+",new:"+newKey,"new");assertThat(new String(rotated.open(cipher,"owner-a"),java.nio.charset.StandardCharsets.UTF_8)).isEqualTo("PRIVATE_Q2_ROTATION");assertThatThrownBy(()->rotated.open(cipher,"owner-b")).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->new PrivateDocumentCipher("old:"+newKey,"old").open(cipher,"owner-a")).isInstanceOf(IllegalStateException.class);cipher[cipher.length-1]^=1;assertThatThrownBy(()->rotated.open(cipher,"owner-a")).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->new PrivateDocumentCipher("new:"+newKey,"new").open(cipher,"owner-a")).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->new PrivateDocumentCipher("","").current()).isInstanceOf(RuntimeException.class);}
}
